import { LOCALES, type Locale } from "./locale";
import { SUMMARY_ENTRIES } from "./summaries";

/**
 * What `npm run summaries:sync` writes, as { path relative to the repo root: file content }. Pure, so
 * tests/summaries.test.ts can rebuild the same files and fail when the committed copies are stale. A locale file that
 * does not exist yet falls back to English here (the sync warns); a work with no English master yet is left out of
 * every generated file (also reported in `missing`). The test still requires every locale × work on disk.
 *
 * - `src/locales/summaries/index/<locale>.json`: every work's name and blurb, so hub lists and related links need no entry chunk
 * - `src/locales/summaries/all.ts`: every work in every locale, for the Worker, prerender and tests
 * - `src/locales/summaries/loaders/<locale>.ts`: one lazy chunk per work, for the client
 * - `src/locales/packs/summaries-<locale>.ts`: the summaries pack (hub copy + list + meta), loaded only on summaries pages
 */
export function summariesSyncFiles(read: (path: string) => string | null): { files: Record<string, string>; missing: string[] } {
  const files: Record<string, string> = {};
  const missing: string[] = [];
  const header = "// Generated by `npm run summaries:sync`; do not edit.";

  const entries = SUMMARY_ENTRIES.filter((id) => {
    const path = `src/locales/summaries/en/${id}.json`;
    if (read(path) !== null) return true;
    missing.push(path);
    return false;
  });
  /** Which locale's file stands in for `<locale>/<id>.json` (or `<locale>.json` when id is null). */
  const sourceLocale = (locale: Locale, id: string | null): Locale => {
    const path = id ? `src/locales/summaries/${locale}/${id}.json` : `src/locales/summaries/${locale}.json`;
    if (locale === "en" || read(path) !== null) return locale;
    missing.push(path);
    return "en";
  };
  const entryOf = (locale: Locale, id: string): { name: string; blurb: string } => {
    const copy = JSON.parse(read(`src/locales/summaries/${locale}/${id}.json`)!) as { name: string; blurb: string };
    return { name: copy.name, blurb: copy.blurb };
  };

  const sources = Object.fromEntries(LOCALES.map((locale) => [locale, Object.fromEntries(entries.map((id) => [id, sourceLocale(locale, id)]))])) as Record<Locale, Record<string, Locale>>;
  for (const locale of LOCALES) {
    const list = Object.fromEntries(entries.map((id) => [id, entryOf(sources[locale][id], id)]));
    files[`src/locales/summaries/index/${locale}.json`] = JSON.stringify(list, null, 2) + "\n";
  }

  const ident = (locale: string, id: string): string => `${locale.replace("-", "")}_${id.replace(/-/g, "_")}`;
  // Typed per work only while every work has an English master; until then the tables are partial.
  const complete = entries.length === SUMMARY_ENTRIES.length;
  files["src/locales/summaries/all.ts"] = [
    `${header} Every work in every locale, for the Worker, prerender and tests; the client loads one at a time.`,
    ...LOCALES.flatMap((locale) => entries.map((id) => `import ${ident(locale, id)} from "./${sources[locale][id]}/${id}.json";`)),
    'import type { SummaryEntryCopy } from "../../shared/summaries-i18n";',
    'import type { SummaryId } from "../../shared/summaries";',
    'import type { Locale } from "../../shared/locale";',
    "",
    "const all = {",
    ...LOCALES.map((locale) => `  ${JSON.stringify(locale)}: { ${entries.map((id) => `${JSON.stringify(id)}: ${ident(locale, id)}`).join(", ")} },`),
    `} satisfies Record<Locale, ${complete ? "Record" : "Partial<Record"}<SummaryId, unknown>${complete ? "" : ">"}>;`,
    "",
    "// JSON imports type each block union loosely; the shape is checked by tests/summaries.test.ts.",
    "export const SUMMARIES_ALL = all as unknown as Record<Locale, Record<SummaryId, SummaryEntryCopy>>;",
    "",
  ].join("\n");

  // Plain dynamic imports (not import.meta.glob): the prerender bundles the client with esbuild, which has no glob.
  for (const locale of LOCALES) {
    files[`src/locales/summaries/loaders/${locale}.ts`] = [
      `${header} One lazy chunk per summary in this locale, for the client.`,
      'import type { SummaryId } from "../../../shared/summaries";',
      "",
      `const loaders = {`,
      ...entries.map((id) => `  ${JSON.stringify(id)}: () => import("../${sources[locale][id]}/${id}.json"),`),
      `} satisfies ${complete ? "Record" : "Partial<Record"}<SummaryId, () => Promise<unknown>>${complete ? "" : ">"};`,
      "",
      "export const SUMMARY_LOADERS = loaders as Record<SummaryId, () => Promise<unknown>>;",
      "",
    ].join("\n");
    files[`src/locales/packs/summaries-${locale}.ts`] = [
      `${header} Summaries hub copy, work names and blurbs, loaded only on /summaries/ pages.`,
      `import hub from "../summaries/${sourceLocale(locale, null)}.json";`,
      `import list from "../summaries/index/${locale}.json";`,
      // Kind, creator, years, related ids and sources ride in the pack (one shared chunk), not the entry bundle.
      'import meta from "../../shared/summaries-meta.json";',
      'import type { SummariesMessages } from "../../shared/messages";',
      'import type { SummaryMeta } from "../../shared/summaries-meta";',
      'import type { SummaryId } from "../../shared/summaries";',
      "",
      "export default {",
      "  ...hub,",
      "  list: list as Record<SummaryId, { name: string; blurb: string }>,",
      "  meta: meta as unknown as Record<SummaryId, SummaryMeta>,",
      "} satisfies SummariesMessages;",
      "",
    ].join("\n");
  }
  return { files, missing: [...new Set(missing)] };
}
